def _codex_fast_on(value: Optional[str]) -> bool:
    """0.144.1 accepts ``fast`` but reports the persisted tier as ``priority``."""
    return value in CODEX_FAST_SERVICE_TIERS


def _codex_terminal_status(message: dict) -> str:
    params = message.get("params")
    turn = params.get("turn") if isinstance(params, dict) else None
    status = turn.get("status") if isinstance(turn, dict) else None
    if isinstance(turn, dict) and turn.get("error") is not None:
        if not status or status == "completed":
            return "failed"
    return status if isinstance(status, str) and status else "completed"


def _codex_success_terminal(message: dict, fallback_turn_id: str) -> TurnEnd:
    params = message.get("params")
    turn = params.get("turn") if isinstance(params, dict) else None
    turn = turn if isinstance(turn, dict) else {}
    turn_id = turn.get("id")
    if not isinstance(turn_id, str) or not turn_id:
        turn_id = fallback_turn_id
    duration = turn.get("durationMs")
    try:
        duration_ms = max(0, int(duration or 0))
    except (TypeError, ValueError):
        duration_ms = 0
    terminal = TurnEnd(
        result=TurnResult(
            subtype="success", duration_ms=duration_ms, is_error=False),
        turn_id=turn_id,
    )
    terminal._codex_authoritative_terminal = True
    return terminal


def _codex_user_message_identity(
    message: dict,
) -> tuple[str, str] | None:
    """Return the official client/turn identity for one userMessage item."""
    if message.get("method") not in {"item/started", "item/completed"}:
        return None
    params = message.get("params")
    item = params.get("item") if isinstance(params, dict) else None
    if not isinstance(item, dict) or item.get("type") != "userMessage":
        return None
    client_id = item.get("clientId")
    turn_id = params.get("turnId")
    if (
        not isinstance(client_id, str)
        or not client_id
        or len(client_id) > 128
        or not isinstance(turn_id, str)
        or not turn_id
        or len(turn_id) > 128
    ):
        return None
    return client_id, turn_id


def _turn_detail_event_group(event: dict) -> str | None:
    """Return the display-block identity used for intra-turn pagination."""
    event_type = event.get("type")
    if event_type in {"assistant_msg_start", "delta", "assistant_msg_end"}:
        identity = event.get("message_id")
        return f"message:{identity}" if isinstance(identity, str) else None
    if event_type in {"tool_use", "tool_delta", "tool_result"}:
        identity = event.get("tool_use_id")
        return f"tool:{identity}" if isinstance(identity, str) else None
    if event_type in {"process", "turn_plan", "turn_diff"}:
        identity = event.get("item_id")
        return f"item:{identity}" if isinstance(identity, str) else None
    # Control/user/terminal frames reconstruct the turn envelope but do not
    # consume one visible process slot.
    return None


def _rebind_turn_detail_visible_id(
    rows: tuple[dict, ...] | list[dict],
    *,
    indexed_turn_id: str,
    visible_turn_id: str,
) -> list[dict]:
    """Bind one proven rollout detail segment to its official visible id.

    Codex may expose a persisted user item id in the official summary while the
    source-bound rollout index stores that same segment under its rollout user
    id.  The caller has already resolved the exact native turn and segment
    index.  Rebind only that verified one-turn group; never guess from prompt
    text or accept an unrelated singleton detail response.
    """
    copied = [dict(row) for row in rows]
    if indexed_turn_id == visible_turn_id:
        return copied
    projected = materialize_history_turns(copied)
    if (
        len(projected) != 1
        or projected[0].get("id") != indexed_turn_id
    ):
        raise ValueError("rollout detail identity is not the resolved segment")
    rebound = False
    for event in copied:
        if event.get("msg_id") == indexed_turn_id:
            event["msg_id"] = visible_turn_id
            rebound = True
    if not rebound:
        raise ValueError("rollout detail has no visible user anchor")
    rebound_projection = materialize_history_turns(copied)
    if (
        len(rebound_projection) != 1
        or rebound_projection[0].get("id") != visible_turn_id
    ):
        raise ValueError("rollout detail could not bind the official identity")
    return copied


def _coalesce_turn_detail_group(rows: list[dict]) -> list[dict]:
    """Fold repeated live snapshots without changing the rendered block.

    A display block is the atomic pagination unit.  Some app-server activities
    emit thousands of snapshots for one item id; replaying every snapshot makes
    that single atomic group larger than the WebSocket frame even though the UI
    ultimately retains only the last merged block.
    """
    if not rows:
        return []
    event_types = {row.get("type") for row in rows}
    if event_types == {"process"}:
        merged = dict(rows[0])
        for row in rows[1:]:
            append_to = row.get("append_to")
            delta = row.get("delta")
            if isinstance(append_to, str) and isinstance(delta, str):
                field = "progress" if append_to == "progress" else append_to
                current = merged.get(field)
                merged[field] = (
                    (current if isinstance(current, str) else "") + delta
                )
            else:
                for key, value in row.items():
                    if value is not None and key not in {"append_to", "delta"}:
                        merged[key] = value
        merged["append_to"] = None
        merged["delta"] = None
        return [merged]
    if event_types == {"turn_plan"} or event_types == {"turn_diff"}:
        return [dict(rows[-1])]
    if event_types <= {
        "assistant_msg_start", "delta", "assistant_msg_end",
    }:
        start = next(
            (dict(row) for row in rows
             if row.get("type") == "assistant_msg_start"),
            None,
        )
        deltas = [
            row.get("text") for row in rows
            if row.get("type") == "delta"
            and isinstance(row.get("text"), str)
        ]
        end = next(
            (dict(row) for row in reversed(rows)
             if row.get("type") == "assistant_msg_end"),
            None,
        )
        result: list[dict] = []
        if start is not None:
            result.append(start)
        if deltas:
            template = next(
                dict(row) for row in rows if row.get("type") == "delta")
            template["text"] = "".join(deltas)
            result.append(template)
        if end is not None:
            result.append(end)
        return result
    if event_types <= {"tool_use", "tool_delta", "tool_result"}:
        result = []
        use = next(
            (dict(row) for row in rows if row.get("type") == "tool_use"),
            None,
        )
        if use is not None:
            result.append(use)
        deltas: dict[str, dict] = {}
        delta_order: list[str] = []
        for row in rows:
            if row.get("type") != "tool_delta":
                continue
            stream = row.get("stream")
            if not isinstance(stream, str):
                continue
            if stream not in deltas:
                deltas[stream] = dict(row)
                deltas[stream]["delta"] = ""
                delta_order.append(stream)
            value = row.get("delta")
            if isinstance(value, str):
                deltas[stream]["delta"] += value
        result.extend(deltas[stream] for stream in delta_order)
        completed = next(
            (dict(row) for row in reversed(rows)
             if row.get("type") == "tool_result"),
            None,
        )
        if completed is not None:
            result.append(completed)
        return result
    # Mixed legacy groups are uncommon and already bounded per event. Preserve
    # their exact order; the final budget guard below still prevents an
    # oversized frame.
    return [dict(row) for row in rows]


def _bound_turn_detail_group(rows: list[dict], max_bytes: int) -> list[dict]:
    """Last-resort field compaction for one otherwise oversized atomic group."""
    if len(json.dumps(
        rows, ensure_ascii=False, separators=(",", ":"),
    ).encode("utf-8")) <= max_bytes:
        return rows
    bounded = []
    for row in rows:
        item = dict(row)
        if item.get("type") == "tool_use":
            item["input"] = {
                "_cc_remote_notice": "工具输入过大，已在此详情页截断",
            }
        elif item.get("type") == "process" and item.get("input") is not None:
            item["input"] = {
                "_cc_remote_notice": "处理输入过大，已在此详情页截断",
            }
        for key in (
            "text", "delta", "content", "summary", "detail", "output",
            "diff", "progress", "command", "explanation",
        ):
            value = item.get(key)
            if isinstance(value, str) and len(value) > 256 * 1024:
                item[key] = value[:256 * 1024] + "\n…（内容过大，已截断）"
                item["truncated"] = True
        bounded.append(item)
    if len(json.dumps(
        bounded, ensure_ascii=False, separators=(",", ":"),
    ).encode("utf-8")) <= max_bytes:
        return bounded

    template = rows[-1]
    base = {
        key: template[key] for key in ("v", "ts", "sid", "seq")
        if key in template
    }
    message = "此处理项本身超过单帧上限，已在本页显式截断。"
    group = _turn_detail_event_group(template)
    if group and group.startswith("message:"):
        message_id = group.removeprefix("message:")
        return [
            {**base, "type": "assistant_msg_start",
             "message_id": message_id, "channel": "unknown"},
            {**base, "type": "delta", "message_id": message_id,
             "text": message, "channel": "unknown"},
            {**base, "type": "assistant_msg_end",
             "message_id": message_id, "channel": "unknown"},
        ]
    if group and group.startswith("tool:"):
        tool_id = group.removeprefix("tool:")
        return [
            {**base, "type": "tool_use", "message_id": tool_id,
             "tool_use_id": tool_id, "tool": "oversized_detail",
             "input": {"notice": message}},
            {**base, "type": "tool_result", "tool_use_id": tool_id,
             "content": message, "is_error": False, "truncated": True},
        ]
    item_id = (
        group.removeprefix("item:")
        if group and group.startswith("item:")
        else f"oversized-detail-{hashlib.sha256(message.encode()).hexdigest()[:16]}"
    )
    return [{
        **base,
        "type": "process",
        "item_id": item_id,
        "kind": "task",
        "phase": "snapshot",
        "status": "succeeded",
        "title": "处理项过大",
        "summary": message,
        "truncated": True,
    }]


def _turn_detail_page(
    rows: tuple[dict, ...] | list[dict],
    *,
    before: str | None,
    limit: int,
    max_bytes: int | None = None,
) -> tuple[list[dict], bool, str | None, bool, str | None]:
    """Select a source-ordered, block-complete detail window."""
    grouped_rows: dict[str, list[dict]] = {}
    for row in rows:
        group = _turn_detail_event_group(row)
        if group is not None:
            grouped_rows.setdefault(group, []).append(row)
    coalesced_groups = {
        group: _bound_turn_detail_group(
            _coalesce_turn_detail_group(group_rows),
            max_bytes or 8 * 1024 * 1024,
        )
        for group, group_rows in grouped_rows.items()
    }

    event_groups: list[str | None] = []
    wire_rows: list[dict] = []
    ordered_groups: list[str] = []
    seen: set[str] = set()
    group_bytes: dict[str, int] = {}
    envelope_bytes = 0
    emitted_groups: set[str] = set()
    source_rows: list[dict] = []
    for row in rows:
        group = _turn_detail_event_group(row)
        if group is None:
            source_rows.append(row)
        elif group not in emitted_groups:
            emitted_groups.add(group)
            source_rows.extend(coalesced_groups[group])
    for row in source_rows:
        group = _turn_detail_event_group(row)
        event_groups.append(group)
        wire_row = {
            **row,
            # Conversation images already have source-bound thumbnail/full
            # endpoints. Never put their base64 bodies back into a heavy detail
            # frame; the summary row retains canonical imageRefs in the browser.
            **({"images": None} if row.get("type") == "user_msg"
               and row.get("images") else {}),
        }
        wire_rows.append(wire_row)
        row_bytes = len(json.dumps(
            wire_row, ensure_ascii=False, separators=(",", ":"),
        ).encode("utf-8"))
        if group is None:
            envelope_bytes += row_bytes
        else:
            group_bytes[group] = group_bytes.get(group, 0) + row_bytes
        if group is not None and group not in seen:
            seen.add(group)
            ordered_groups.append(group)

    total = len(ordered_groups)
    requested_end: int | None = None
    if before is not None:
        if not before.isascii() or not before.isdigit():
            raise ValueError("invalid turn detail cursor")
        requested_end = int(before)
        if requested_end < 0 or requested_end > total:
            raise ValueError("turn detail cursor is out of range")
    page_limit = max(1, limit)

    def page_start(end: int) -> int:
        start = end
        page_bytes = envelope_bytes
        while start > 0 and end - start < page_limit:
            candidate = ordered_groups[start - 1]
            candidate_bytes = group_bytes.get(candidate, 0)
            if (max_bytes is not None and start < end
                    and page_bytes + candidate_bytes > max_bytes):
                break
            start -= 1
            page_bytes += candidate_bytes
        return start

    # Derive one canonical page chain from newest to oldest. Byte-bounded pages
    # can contain fewer than ``limit`` groups, so adding ``limit`` to the current
    # cursor can skip a whole intermediate page. Only advertise exact adjacent
    # boundaries from this chain in either direction.
    boundaries = [total]
    while boundaries[-1] > 0:
        boundaries.append(page_start(boundaries[-1]))
    end = total if requested_end is None else requested_end
    try:
        boundary_index = boundaries.index(end)
    except ValueError as exc:
        raise ValueError("turn detail cursor is not a page boundary") from exc
    start = (
        boundaries[boundary_index + 1]
        if boundary_index + 1 < len(boundaries)
        else end
    )
    selected = set(ordered_groups[start:end])
    page = [
        dict(row) for row, group in zip(wire_rows, event_groups)
        if group is None or group in selected
    ]
    has_more = start > 0
    oldest_cursor = str(start) if has_more else None
    has_newer = boundary_index > 0
    newer_cursor = (
        str(boundaries[boundary_index - 1]) if has_newer else None
    )
    return page, has_more, oldest_cursor, has_newer, newer_cursor


_TURN_DETAIL_SNAPSHOT_CURSOR_PREFIX = "td1"


@dataclass(frozen=True)
class _TurnDetailSnapshotCursor:
    source_token: str
    visible_turn_hash: str
    indexed_turn_hash: str
    before: str


def _encode_turn_detail_snapshot_cursor(
    *,
    source_token: str,
    visible_turn_id: str,
    indexed_turn_id: str,
    before: str | None,
) -> str | None:
    if before is None:
        return None
    cursor = ".".join((
        _TURN_DETAIL_SNAPSHOT_CURSOR_PREFIX,
        source_token,
        history_turn_snapshot_hash(visible_turn_id),
        history_turn_snapshot_hash(indexed_turn_id),
        before,
    ))
    if len(cursor) > 128:
        raise ValueError("turn detail snapshot cursor exceeds wire limit")
    return cursor


def _decode_turn_detail_snapshot_cursor(
    value: str | None,
) -> _TurnDetailSnapshotCursor | None:
    if value is None or not value.startswith(
            f"{_TURN_DETAIL_SNAPSHOT_CURSOR_PREFIX}."):
        return None
    parts = value.split(".")
    if (
        len(parts) != 5
        or parts[0] != _TURN_DETAIL_SNAPSHOT_CURSOR_PREFIX
        or len(parts[1]) != 64
        or any(char not in "0123456789abcdef" for char in parts[1])
        or len(parts[2]) != 16
        or any(char not in "0123456789abcdef" for char in parts[2])
        or len(parts[3]) != 16
        or any(char not in "0123456789abcdef" for char in parts[3])
        or not parts[4].isascii()
        or not parts[4].isdigit()
    ):
        raise ValueError("invalid turn detail snapshot cursor")
    return _TurnDetailSnapshotCursor(
        source_token=parts[1],
        visible_turn_hash=parts[2],
        indexed_turn_hash=parts[3],
        before=parts[4],
    )


def _render_history_image(
    image: dict,
    variant: str,
) -> tuple[str, int, int, bytes]:
    """Validate and optionally thumbnail one indexed historical image."""
    media_type = image.get("media_type")
    encoded = image.get("data")
    if not isinstance(media_type, str) or not isinstance(encoded, str):
        raise ValueError("历史图片数据无效")
    if validate_attachments([image], None) is not None:
        raise ValueError("历史图片超出安全限制")
    raw = decode_attachment(encoded)
    dimensions = image_dimensions(raw, media_type)
    if dimensions is None:
        raise ValueError("历史图片格式无效")
    width, height = dimensions
    if width * height > MAX_IMAGE_PIXELS:
        raise ValueError("历史图片尺寸过大")
    normalized = "image/jpeg" if media_type == "image/jpg" else media_type
    if variant == "full":
        return normalized, width, height, raw

    from PIL import Image

    Image.MAX_IMAGE_PIXELS = MAX_IMAGE_PIXELS
    with Image.open(io.BytesIO(raw)) as source:
        if int(getattr(source, "n_frames", 1)) != 1:
            raise ValueError("动态图片暂不支持预览")
        source.load()
        source.thumbnail((360, 360), Image.Resampling.LANCZOS)
        if source.mode not in {"RGB", "RGBA"}:
            source = source.convert("RGBA" if "transparency" in source.info else "RGB")
        output = io.BytesIO()
        source.save(
            output,
            format="WEBP",
            lossless=normalized == "image/png",
            quality=82,
            method=4,
        )
        thumb = output.getvalue()
        if len(thumb) > 512 * 1024:
            source.thumbnail((240, 240), Image.Resampling.LANCZOS)
            output = io.BytesIO()
            source.convert("RGB").save(
                output, format="WEBP", quality=70, method=4)
            thumb = output.getvalue()
        return "image/webp", source.width, source.height, thumb


@dataclass(frozen=True)
class _MaterializedClaudeHistoryImage:
    turn_id: str
    image_id: str
    media_type: str
    width: int
    height: int
    data: bytes | None


def _validate_claude_history_image(
    asset: ClaudeHistoryImageAsset,
) -> tuple[dict[str, object], str, int, int, bytes] | None:
    image = {"media_type": asset.media_type, "data": asset.data}
    if validate_attachments([image], None) is not None:
        return None
    try:
        data = decode_attachment(asset.data)
    except ValueError:
        return None
    dimensions = image_dimensions(data, asset.media_type)
    if dimensions is None:
        return None
    width, height = dimensions
    media_type = (
        "image/jpeg" if asset.media_type == "image/jpg" else asset.media_type
    )
    return ({
        "image_id": asset.image_id,
        "media_type": media_type,
        "width": width,
        "height": height,
        "byte_size": len(data),
    }, media_type, width, height, data)


def _attach_claude_history_image_refs(
    groups: list[list],
    assets: tuple[ClaudeHistoryImageAsset, ...],
    *,
    max_cached_bytes: int = MAX_TOTAL_ATTACHMENT_BYTES,
) -> tuple[_MaterializedClaudeHistoryImage, ...]:
    """Attach wire-safe refs only to selected Claude history process rows."""
    by_item: dict[str, ClaudeHistoryImageAsset] = {}
    for asset in assets:
        by_item.setdefault(asset.item_id, asset)
    materialized: list[_MaterializedClaudeHistoryImage] = []
    cached_bytes = 0
    for group in groups:
        turn_id = next((
            event.msg_id for event in group
            if isinstance(event, UserMsg)
        ), None)
        if not isinstance(turn_id, str):
            continue
        for event in group:
            if (
                not isinstance(event, ProcessEvent)
                or event.tool != "view_image"
                or event.phase != "end"
            ):
                continue
            asset = by_item.get(event.item_id)
            if asset is None:
                continue
            validated = _validate_claude_history_image(asset)
            if validated is None:
                continue
            image_ref, media_type, width, height, data = validated
            event.input = {
                **(event.input if isinstance(event.input, dict) else {}),
                "history_image": image_ref,
            }
            cached_data = None
            if cached_bytes + len(data) <= max(0, max_cached_bytes):
                cached_data = data
                cached_bytes += len(data)
            materialized.append(_MaterializedClaudeHistoryImage(
                turn_id=turn_id,
                image_id=asset.image_id,
                media_type=media_type,
                width=width,
                height=height,
                data=cached_data,
            ))
    return tuple(materialized)


def _normalized_tool_name(value: object) -> str:
    return re.sub(r"[^a-z0-9]", "", str(value or "").lower())


def _merge_codex_history_image_views(
    rows: tuple[dict, ...] | list[dict],
    views: tuple[CodexHistoryImageView, ...],
) -> list[dict]:
    """Add only missing image-view rows without replacing official detail."""
    merged = [dict(row) for row in rows]
    if not views:
        return merged

    official_indexes: list[int] = []
    for index, row in enumerate(merged):
        if (
            row.get("type") == "process"
            and _normalized_tool_name(row.get("tool")) in {
                "viewimage", "imagegeneration"}
        ):
            official_indexes.append(index)

    used_official: set[int] = set()
    matched_official_calls: set[str] = set()
    view_events: dict[str, dict] = {}
    for view in views:
        event = view.event.model_dump(mode="json")
        view_events[view.call_id] = event
        event_input = event.get("input")
        image_path = (
            event_input.get("file_path")
            if isinstance(event_input, dict)
            else None
        )
        matched_index = next((
            index for index in official_indexes
            if index not in used_official
            and _normalized_tool_name(merged[index].get("tool"))
            == _normalized_tool_name(event.get("tool"))
            and merged[index].get("item_id") == event.get("item_id")
        ), None)
        image_ref = event_input.get("history_image") if isinstance(event_input, dict) else None
        if matched_index is None and isinstance(image_ref, dict):
            matched_index = next((
                index for index in official_indexes
                if index not in used_official
                and _normalized_tool_name(merged[index].get("tool"))
                == _normalized_tool_name(event.get("tool"))
                and isinstance(merged[index].get("input"), dict)
                and merged[index]["input"].get("history_image") == image_ref
            ), None)
        if matched_index is None and isinstance(image_path, str):
            matched_index = next((
                index for index in official_indexes
                if index not in used_official
                and _normalized_tool_name(merged[index].get("tool"))
                == _normalized_tool_name(event.get("tool"))
                and isinstance(merged[index].get("input"), dict)
                and (
                    merged[index]["input"].get("file_path")
                    or merged[index]["input"].get("path")
                ) == image_path
            ), None)
        if matched_index is not None:
            used_official.add(matched_index)
            official = dict(merged[matched_index])
            official_input = dict(
                official.get("input")
                if isinstance(official.get("input"), dict)
                else {}
            )
            if isinstance(event_input, dict):
                history_ref = event_input.get("history_image")
                if isinstance(history_ref, dict):
                    official_input["history_image"] = history_ref
            if image_path:
                official_input.setdefault("file_path", image_path)
            official["input"] = official_input or None
            official["tool"] = event["tool"]
            merged[matched_index] = official
            matched_official_calls.add(view.call_id)

    legacy_view_calls = {
        str(row.get("tool_use_id"))
        for row in merged
        if (
            row.get("type") == "tool_use"
            and row.get("tool_use_id") in view_events
            and _normalized_tool_name(row.get("tool")) == "viewimage"
        )
    }
    placed_calls: set[str] = set(matched_official_calls)
    base: list[dict] = []
    for row in merged:
        call_id = row.get("tool_use_id")
        if (
            row.get("type") == "tool_use"
            and call_id in legacy_view_calls
        ):
            call_key = str(call_id)
            if call_key not in placed_calls:
                base.append(view_events[call_key])
                placed_calls.add(call_key)
            continue
        if (
            row.get("type") in {"tool_delta", "tool_result"}
            and call_id in legacy_view_calls
        ):
            continue
        base.append(row)

    additions = [
        view for view in views
        if view.call_id not in placed_calls
    ]
    if not additions:
        return base

    first_by_id: dict[str, int] = {}
    last_by_id: dict[str, int] = {}
    for index, row in enumerate(base):
        for key in ("item_id", "tool_use_id", "message_id"):
            identity = row.get(key)
            if not isinstance(identity, str):
                continue
            first_by_id.setdefault(identity, index)
            last_by_id[identity] = index

    fallback_index = next((
        index for index, row in enumerate(base)
        if (
            row.get("type") == "assistant_msg_start"
            and row.get("channel") == "final"
        )
    ), None)
    if fallback_index is None:
        fallback_index = next((
            index for index, row in enumerate(base)
            if row.get("type") == "turn_end"
        ), len(base))

    insertions: dict[int, list[dict]] = {}
    for view in additions:
        if (
            view.next_item_id is not None
            and view.next_item_id in first_by_id
        ):
            insert_at = first_by_id[view.next_item_id]
        elif (
            view.previous_item_id is not None
            and view.previous_item_id in last_by_id
        ):
            insert_at = last_by_id[view.previous_item_id] + 1
        else:
            insert_at = fallback_index
        insertions.setdefault(insert_at, []).append(
            view.event.model_dump(mode="json"))

    ordered: list[dict] = []
    for index in range(len(base) + 1):
        ordered.extend(insertions.get(index, ()))
        if index < len(base):
            ordered.append(base[index])
    return ordered


def _session_permission_mode(ctx: SessionContext) -> str:
    """Return the permission mode actually configured on this live engine."""
    if ctx.engine == "codex":
        return getattr(ctx.sdk, "approval", "never")
    return getattr(ctx.sdk, "permission_mode", "bypassPermissions")


def _session_permission_profile(ctx: SessionContext) -> Optional[str]:
    """Return the official active Codex named profile, when available."""
    if ctx.engine != "codex":
        return None
    value = getattr(ctx.sdk, "permission_profile", None)
    if isinstance(value, str) and value.strip():
        return value.strip()
    return None


def _session_web_search(ctx: SessionContext) -> Optional[str]:
    if ctx.engine != "codex":
        return None
    value = getattr(ctx.sdk, "web_search", None)
    return value if value in CODEX_WEB_SEARCH_MODES else None


def _session_model(ctx: SessionContext) -> Optional[str]:
    """Return the live engine's authoritative per-session model, if known."""
    value = getattr(ctx.sdk, "model", None) or ctx.announced_model
    return value.strip() if isinstance(value, str) and value.strip() else None


def _session_effort(ctx: SessionContext) -> Optional[str]:
    """Return the live engine's effective/display reasoning strength."""
    explicit = getattr(ctx.sdk, "effort", None)
    if isinstance(explicit, str) and explicit.strip():
        return explicit.strip()
    if ctx.engine == "codex" and hasattr(ctx.sdk, "effort"):
        display = getattr(ctx.sdk, "display_effort", None)
        model = _session_model(ctx)
        raw_cwd = getattr(ctx.sdk, "_cwd", None) or ctx.cwd
        cwd = (
            os.path.realpath(raw_cwd)
            if isinstance(raw_cwd, str) and raw_cwd else None
        )
        if (
            isinstance(display, str)
            and display.strip()
            and getattr(ctx.sdk, "display_effort_model", None) == model
            and getattr(ctx.sdk, "display_effort_cwd", None) == cwd
            and getattr(ctx.sdk, "display_effort_generation", None)
                == getattr(ctx.sdk, "_generation", None)
        ):
            return display.strip()
        # A normal Codex handle with an invalidated display projection must not
        # fall back to the previously announced value from another cwd/process.
        return None
    value = getattr(ctx.sdk, "display_effort", None) or ctx.announced_effort
    return value.strip() if isinstance(value, str) and value.strip() else None


def _history_control_rows(
    sid: str,
    ctx: Optional[SessionContext],
    *,
    fallback_model: Optional[str] = None,
    allow_fallback_model: bool = False,
) -> list[dict]:
    """Return the one authoritative model/effort pair for a newest page.

    Transcript control rows describe an earlier point in the conversation.  A
    resident engine (including an ephemeral BTW fork) instead owns the current
    settings readout.  Build that pair once at the History envelope boundary so
    cached and freshly translated pages cannot order an old row after it and
    silently roll the browser back on refresh.
    """
    model = _session_model(ctx) if ctx is not None else None
    if (
        model is None
        and allow_fallback_model
        and isinstance(fallback_model, str)
        and fallback_model.strip()
    ):
        model = fallback_model.strip()
    effort = _session_effort(ctx) if ctx is not None else None
    if ctx is not None and ctx.engine == "codex" and not effort:
        # A null app-server thread override is a real model-default state.  It
        # must replace any stale rollout effort instead of leaving the browser
        # on its previously painted concrete value.
        effort = MODEL_DEFAULT_EFFORT

    rows: list[dict] = []
    if model:
        rows.append(Model(model=model, sid=sid).model_dump(mode="json"))
    if effort:
        rows.append(Effort(effort=effort, sid=sid).model_dump(mode="json"))
    return rows


def _replace_history_control_rows(
    rows: list[dict] | tuple[dict, ...],
    controls: list[dict],
) -> list[dict]:
    """Install one control row per kind before the narrative projection.

    A resident value replaces every transcript/cache copy of the same kind.
    When one side is unavailable (notably a cold, non-resident cache hit), keep
    only the newest source value instead of erasing the best known readout.
    """
    selected = {
        row.get("type"): dict(row)
        for row in rows
        if row.get("type") in {"model", "effort"}
    }
    selected.update({row.get("type"): dict(row) for row in controls})
    return [
        *(selected[kind] for kind in ("model", "effort")
          if kind in selected),
        *(dict(row) for row in rows
          if row.get("type") not in {"model", "effort"}),
    ]


def _codex_active_continuation_ids(
    ctx: Optional[SessionContext],
) -> set[str]:
    """Return every handle-proven active continuation id for translation."""
    if ctx is None or ctx.engine != "codex":
        return set()
    values = getattr(ctx.sdk, "compaction_continuation_turn_ids", frozenset())
    if not isinstance(values, (set, frozenset, tuple, list)):
        return set()
    return {
        value for value in values
        if isinstance(value, str) and value
    }


def _codex_compaction_continuation_ids(
    ctx: Optional[SessionContext],
) -> list[str]:
    """Return the four most relevant handle-proven ids allowed on the wire."""
    values = _codex_active_continuation_ids(ctx)
    if not values or ctx is None:
        return []
    if len(values) <= 4:
        return sorted(values)
    # The wire hint is bounded to four ids. Never let lexical truncation drop
    # the resident control owners; translation receives the complete set.
    priority: list[str] = []
    for candidate in (
        getattr(ctx.sdk, "turn_id", None),
        ctx.codex_owned_turn_id,
        ctx.codex_spontaneous_turn_id,
    ):
        if isinstance(candidate, str) and candidate in values \
                and candidate not in priority:
            priority.append(candidate)
    priority.extend(sorted(values.difference(priority)))
    return priority[:4]


def _codex_list_state(status: Optional[str]) -> Optional[State]:
    if status == "active":
        return "running"
    if status == "idle":
        return "idle"
    return None


def _codex_catalog_sort_key(value: object) -> float:
    try:
        parsed = float(value)
    except (TypeError, ValueError):
        return -1.0
    return parsed if math.isfinite(parsed) else -1.0


def _codex_catalog_default_model(models: list[dict]) -> Optional[str]:
    """Return one normalized catalog default without crossing profiles."""
    available = [
        item for item in models
        if isinstance(item.get("id"), str) and item["id"]
    ]
    if not available:
        return None
    return next((
        item["id"] for item in available if item.get("is_default")
    ), available[0]["id"])


