        self._codex_session_list_refresh_task: Optional[asyncio.Task] = None
        self._codex_session_list_epoch = 0
        self._codex_session_list_refresh_epoch = -1
        self._codex_session_profile_errors: tuple[tuple[str, str], ...] = ()
